export const STORES = [
 {id:'qinghe',name:'青禾小馆',english:'QINGHE KITCHEN',area:'街角家常',meal:'香菇鸡腿饭',description:'一碗家常饭，把日子过得热乎一点。',detail:'慢炖鸡腿与香菇，搭配清炒时蔬和一碗米饭。简单、认真，像熟悉的家常味道。',price:6,image:'hero-meal.jpg',type:'meat',windows:[[690,810],[1020,1200]],windowLabel:'11:30–13:30 / 17:00–20:00'},
 {id:'shiguang',name:'拾光食堂',english:'SHIGUANG TABLE',area:'清爽时蔬',meal:'田园时蔬碗',description:'把四季装进碗里，把暖意留在心里。',detail:'缤纷蔬菜搭配谷物与清爽酱汁，用朴素的食材做一份轻盈而丰盛的午晚膳。',price:5,image:'vegetables.jpg',type:'veg',windows:[[660,840],[1050,1200]],windowLabel:'11:00–14:00 / 17:30–20:00'},
 {id:'nuanxiang',name:'暖巷饭铺',english:'NUANXIANG BOWL',area:'邻里小店',meal:'暖心谷物沙拉',description:'巷子里的小店，总有一份为你留着。',detail:'谷物、时令蔬菜与香草组成一碗暖心餐食。每天认真准备，给下一位留一份踏实。',price:4,image:'bowl.jpg',type:'veg',windows:[[690,840],[1020,1170]],windowLabel:'11:30–14:00 / 17:00–19:30'}
];
export const H72=72*60*60*1000;
export const getStore=id=>STORES.find(s=>s.id===id);
export function initialState(now=Date.now()) {
 const units=[], orders=[]; const configs={}; let seq=0;
 for(const [i,s] of STORES.entries()){
  configs[s.id]={active:true,paused:false,version:1,price:s.price,meal:s.meal};
  const count=[6,4,3][i]; const order={id:`SEED-${i+1}`,store:s.id,quantity:count,price:s.price,version:1,meal:s.meal,time:now-7200000,owner:'seed',nft:false};orders.push(order);
  for(let n=0;n<count;n++) units.push({id:++seq,order:order.id,store:s.id,status:n===0?'S':n===1?'H':'A',price:s.price,version:1});
 }
 return {schema:1,units,orders,configs,coupons:[],events:[],wallet:false,merchant:null,clockOffset:0,nextUnit:seq};
}
export const nowFor=s=>Date.now()+(s.clockOffset||0);
export function stats(s,store){const u=s.units.filter(x=>!store||x.store===store);return Object.fromEntries(['F','A','R','H','S','X'].map(k=>[k,k==='F'?u.length:u.filter(x=>x.status===k).length]));}
export function inWindow(store,now){const d=new Date(now); const mins=Number(new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(d).split(':')[0])*60+Number(new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Shanghai',minute:'2-digit'}).format(d));const w=store.windows.find(([a,b])=>mins>=a&&mins<b); return w?now+(w[1]-mins)*60000-d.getUTCSeconds()*1000-d.getUTCMilliseconds():0;}
export function expire(s,now){for(const c of s.coupons){if(c.status==='issued'&&c.expires<=now){c.status='expired';const u=s.units.find(u=>u.id===c.unit);if(u?.status==='R')u.status='A';}}}
export function support(s,id,qty,nft,now){const c=s.configs[id];if(!s.wallet)throw Error('请先进入体验钱包。');if(!c.active||c.paused)throw Error('本店暂不接受新支持。');if(!Number.isInteger(qty)||qty<1||stats(s,id).F+qty>10)throw Error('本店累计支持上限为 10 份。');const o={id:'MF-'+crypto.randomUUID().slice(0,8).toUpperCase(),store:id,quantity:qty,price:c.price,version:c.version,meal:c.meal,time:now,owner:'demo-wallet',nft:nft?'queued':false};s.orders.push(o);for(let n=0;n<qty;n++)s.units.push({id:++s.nextUnit,order:o.id,store:id,status:'A',price:c.price,version:c.version});s.events.unshift({time:now,store:id,label:'支持付款 · 模拟最终确认',qty});return o;}
export function claim(s,id,emailHash,now){expire(s,now);if(!s.configs[id].active||s.configs[id].paused)throw Error('本店暂不发行新券。');const prior=s.coupons.find(c=>c.emailHash===emailHash&&now-c.issued<H72);if(prior)throw Error('同一邮箱全平台 72 小时内只能领取一份，请找回原券。');const u=s.units.find(u=>u.store===id&&u.status==='A');if(!u)throw Error('本店暂时没有可领餐份，稍后再来看看。');u.status='R';const order=s.orders.find(o=>o.id===u.order);const c={id:'C-'+crypto.randomUUID().slice(0,8).toUpperCase(),emailHash,store:id,unit:u.id,issued:now,expires:now+H72,status:'issued',price:u.price,meal:order.meal,version:u.version,token:null,tokenExpires:0};s.coupons.push(c);s.events.unshift({time:now,store:id,label:'发行餐券 · 模拟',qty:1});return c;}
export function credential(s,c,now){expire(s,now);if(c.status!=='issued')throw Error('这张券目前无法生成核验凭证。');const end=inWindow(getStore(c.store),now);if(!end)throw Error('请在公布的供餐窗口内生成核验凭证。');if(s.configs[c.store].paused)throw Error('本店安全暂停中，暂不可核券。');const b=new Uint8Array(32);crypto.getRandomValues(b);c.token=Array.from(b,x=>x.toString(16).padStart(2,'0')).join('');c.tokenExpires=Math.min(now+120000,c.expires,end);return c.token;}
export function checkToken(s,id,token,now){expire(s,now);const c=s.coupons.find(c=>c.store===id&&c.token===token);if(!c||c.status!=='issued'||c.tokenExpires<=now||!inWindow(getStore(id),now))throw Error('凭证无效、已过期或当前不在供餐窗口。');if(s.merchant!==id)throw Error('请认证本店演示老板身份。');if(s.configs[id].paused)throw Error('本店安全暂停中，不能新交餐。');return c;}
export function lock(s,id,token,now){const c=checkToken(s,id,token,now);c.status='locked';return c;}
export function report(s,c,now){if(s.merchant!==c.store||c.status!=='locked')throw Error('必须由本店老板在唯一锁定后申报。');if(!inWindow(getStore(c.store),now)||now>=c.expires||s.configs[c.store].paused)throw Error('已超出交餐条件，锁定责任保留，请核查原操作。');c.status='reported';s.units.find(u=>u.id===c.unit).status='H';s.events.unshift({time:now,store:c.store,label:'交餐申报 · 模拟最终确认',qty:1});}
export function refund(s,orderId,now){const o=s.orders.find(o=>o.id===orderId);if(!s.wallet||o?.owner!=='demo-wallet')throw Error('请恢复原付款体验钱包。');const units=s.units.filter(u=>u.order===orderId&&u.status==='A');if(!units.length)throw Error('没有可安全退款的自由份额。');for(const u of units)u.status='X';s.events.unshift({time:now,store:o.store,label:'自由份额返还 · 模拟',qty:units.length});return units.length;}
export function settle(s,id,now){if(s.merchant!==id)throw Error('请认证本店老板身份。');const units=s.units.filter(u=>u.store===id&&u.status==='H');if(!units.length)throw Error('暂无待结算款项。');for(const u of units)u.status='S';const amount=units.reduce((t,u)=>t+u.price,0);s.events.unshift({time:now,store:id,label:'老板本人结算 · 模拟到账',qty:units.length});return amount;}
